const root=document.getElementById('admin-root'),dialog=document.getElementById('admin-dialog'),detail=document.getElementById('admin-detail');
const titles={dashboard:'Fine Form',analytics:'Estatísticas',quotes:'Pedidos',subscriptions:'Fine Form Care',plates:'Placas',agenda:'Agenda',customers:'Clientes',notifications:'Notificações',settings:'Dados e operação'};
const subLabels={active:'Ativo',paused:'Pausado',cancelled:'Cancelado'},visitStates={scheduled:'Agendada',in_progress:'Em cuidado',completed:'Concluída',cancelled:'Cancelada'};
const transitions={pending:['accepted','declined','cancelled'],accepted:['in_progress','ready','completed','cancelled'],in_progress:['ready','completed','cancelled'],ready:['completed','cancelled'],declined:[],completed:[],cancelled:[]};
let tab='dashboard',page=0,search='',filter='',agendaDate=todaySP(),stop,loading=false,needRefresh=false,currentQuote,currentSub,currentCustomer,toastTimer,sessionTimer,authDialogPromise,authDialog;
let dashboardWeekOffset=0;
let stopAdminHeaderGlass=()=>{};
let mfaRequired=!['localhost','127.0.0.1','[::1]'].includes(location.hostname);
const notificationId=value=>typeof value==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const notificationEditor=()=>document.activeElement?.matches('input,select,textarea')&&!document.activeElement.closest('dialog:not([open])');
let pendingNotification=new URL(location.href).searchParams.get('pedido'),openingNotification=false;
async function openPendingNotification(){
 if(!notificationId(pendingNotification)||openingNotification||loading||!document.getElementById('admin-view')||dialog.open||notificationEditor())return;
 const id=pendingNotification;pendingNotification=null;openingNotification=true;
 const url=new URL(location.href);url.searchParams.delete('pedido');history.replaceState(null,'',url);
 try{await openQuote(id);}catch(error){toast(error.status===404?'Este pedido já não está disponível.':error.message);}finally{openingNotification=false;}
}
navigator.serviceWorker?.addEventListener('message',event=>{
 if(event.data?.type!=='ff-open-order'||!notificationId(event.data.quoteId))return;
 let source;try{source=new URL(event.source?.scriptURL);}catch{return;}
 if(source.origin!==location.origin||source.pathname!=='/painel/sw.js')return;
 pendingNotification=event.data.quoteId;
 const url=new URL(location.href);url.searchParams.set('pedido',pendingNotification);history.replaceState(null,'',url);
 if(dialog.open||notificationEditor())toast('Há um novo pedido. Termine esta edição para abri-lo.');
 else openPendingNotification();
});
function toast(value){const el=document.getElementById('admin-toast');el.textContent=value;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,6500);}
function badge(status,label=statusLabel[status]||subLabels[status]||visitStates[status]){return '<span class="status-badge status-'+e(status)+'">'+e(label)+'</span>';}
const field=(name,label,value='',type='text',attrs='')=>'<label class="system-field"><span>'+label+'</span><input name="'+name+'" type="'+type+'" value="'+e(value)+'" '+attrs+'></label>';
const area=(name,label,value='',max=600)=>'<label class="system-field"><span>'+label+'</span><textarea name="'+name+'" maxlength="'+max+'">'+e(value)+'</textarea></label>';
const select=(name,label,options,value='')=>'<label class="system-field"><span>'+label+'</span><select name="'+name+'">'+options.map(([id,title])=>'<option value="'+e(id)+'" '+(id===value?'selected':'')+'>'+e(title)+'</option>').join('')+'</select></label>';
const paid='<label class="system-check"><input name="paidConfirmed" type="checkbox" required><span>Recebi o pagamento deste ciclo e conferi o valor.</span></label>';
const blank=message=>'<div class="system-empty">'+message+'</div>';
const period=c=>c?dateLabel(c.starts_on)+' → '+dateLabel(c.ends_on)+' (fim exclusivo)':'Sem ciclo';
function modal(html){currentCustomer=null;dialog.classList.toggle('ff-quote-dialog',html.includes('ff-quote-view'));detail.innerHTML='<p id="dialog-error" class="system-error ff-dialog-error" role="alert" hidden></p>'+html;if(!dialog.open)dialog.showModal();detail.querySelector('h2')?.focus({preventScroll:true});}
function modalError(error){const el=document.getElementById('dialog-error');if(el){el.textContent=error.message;el.hidden=false;el.scrollIntoView({block:'start'});}else toast(error.message);}
const adminIcons={"analytics":"M4 20V10 M12 20V4 M20 20v-7","dashboard":"M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z","quotes":"M8 3h9l4 4v14H8z M17 3v5h4 M10 12h8 M10 16h8","subscriptions":"M4 6h16v12H4z M4 10h16 M8 15h4","plates":"M3 7h18v10H3z M6 11h6 M16 11h2 M6 14h12","agenda":"M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18 M8 14h3","customers":"M16 20v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 10a4 4 0 1 0 0-8a4 4 0 0 0 0 8 M16 4a3 3 0 0 1 0 6","notifications":"M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4","settings":"M12 15a3 3 0 1 0 0-6a3 3 0 0 0 0 6 M12 2v3 M12 19v3 M4.93 4.93l2.12 2.12 M16.95 16.95l2.12 2.12 M2 12h3 M19 12h3 M4.93 19.07l2.12-2.12 M16.95 7.05l2.12-2.12"};
const adminNavIcon=id=>'<svg class="admin-nav-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="'+adminIcons[id]+'"/></svg>';
const searchIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg>';
const moreIcon='<svg class="admin-nav-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg>';
function closeMore(restoreFocus=false){const menu=document.getElementById('admin-more-menu'),button=root.querySelector('[data-action="more"]'),headerButton=root.querySelector('[data-action="header-more"]');const fromHeader=headerButton?.getAttribute('aria-expanded')==='true';if(menu)menu.hidden=true;button?.setAttribute('aria-expanded','false');headerButton?.setAttribute('aria-expanded','false');if(restoreFocus)(fromHeader?headerButton:button)?.focus();}
function shell(){
 const nav=[['dashboard','Início'],['quotes','Pedidos'],['agenda','Agenda'],['subscriptions','Care'],['plates','Placas'],['customers','Clientes'],['analytics','Estatísticas'],['notifications','Notificações'],['settings','Dados']];
 const navButton=([id,label])=>'<button type="button" data-tab="'+id+'" aria-label="'+e(label)+'" '+(id===tab?'aria-current="page"':'')+'>'+adminNavIcon(id)+'<span>'+label+'</span></button>';
 root.innerHTML='<div class="admin-shell" data-active="'+tab+'"><aside class="admin-sidebar"><a class="admin-brand" href="../" aria-label="Fine Form, abrir site"><img src="../assets/logo-original.png" alt="" width="40" height="40"><span>FINE FORM<small>ESTÉTICA AUTOMOTIVA</small></span></a><nav class="admin-nav" aria-label="Gestão">'+nav.map(navButton).join('')+'</nav><div class="admin-sidebar-bottom"><button type="button" class="button orange" data-action="new-sub">＋ Novo Care</button><a href="../" target="_blank" rel="noopener">Abrir site ↗</a><button type="button" data-action="logout">Sair do painel</button></div></aside><main class="admin-main" id="admin-main" tabindex="-1"><header class="site-header admin-glass-header" data-admin-header aria-label="Fine Form"><div class="ff-header-menu"><button class="nav-toggle admin-site-menu" type="button" data-action="header-more" aria-expanded="false" aria-controls="admin-more-menu" aria-label="Abrir menu"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div><a class="brand ff-header-mark" href="../" aria-label="Fine Form, abrir site"><img src="../assets/logo-transparent.svg" alt="" width="42" height="42"></a></header><header class="admin-appbar"><a class="admin-profile-logo" href="../" aria-label="Fine Form, abrir site"><img src="../assets/logo-original.png" alt="" width="40" height="40"></a><button class="admin-back" data-tab="dashboard" type="button" aria-label="Voltar ao início"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg></button><div class="admin-header-copy"><p><span id="admin-greeting">Olá, Mateus</span><span id="admin-live" class="live-state" role="status">Conectando atualizações…</span></p><h1 id="view-title">'+titles[tab]+'</h1></div><div class="admin-header-actions"><button class="admin-header-icon" data-tab="agenda" type="button" aria-label="Abrir agenda">'+adminNavIcon('agenda')+'</button><button class="admin-header-icon" data-tab="notifications" type="button" aria-label="Notificações">'+adminNavIcon('notifications')+'</button></div></header><div class="admin-workspace"><form class="admin-global-search" id="admin-search" role="search"><button type="submit" aria-label="Buscar pedidos">'+searchIcon+'</button><input name="q" type="search" maxlength="60" placeholder="Buscar placa, nome ou telefone" aria-label="Buscar pedidos por placa, nome ou telefone" autocomplete="off"><button type="button" data-tab="quotes" aria-label="Todos os pedidos">'+adminNavIcon('quotes')+'</button></form><p id="pending-update" class="admin-note-banner" hidden>Há atualizações. Salve o que está editando e toque em Atualizar.</p><div id="admin-view"></div></div><nav class="admin-mobile-nav" aria-label="Navegação do painel">'+navButton(nav[0])+navButton(nav[1])+'<button class="admin-create-care" data-action="new-sub" type="button" aria-label="Cadastrar novo Care"><i aria-hidden="true">＋</i><span>Novo Care</span></button>'+navButton(nav[2])+'<button data-action="more" type="button" aria-label="Mais opções" aria-expanded="false" aria-controls="admin-more-menu">'+moreIcon+'<span>Menu</span></button></nav></main><section class="admin-more-menu" id="admin-more-menu" aria-label="Mais opções de gestão" hidden><div class="admin-more-heading"><h2>Seu estúdio</h2><button data-action="close-more" type="button" aria-label="Fechar opções">×</button></div>'+nav.slice(3).map(navButton).join('')+'<button type="button" data-action="refresh">Atualizar painel ↻</button><a href="../" target="_blank" rel="noopener">Abrir site ↗</a><button type="button" data-action="logout">Sair do painel</button></section></div>';
 stopAdminHeaderGlass();stopAdminHeaderGlass=mountHeaderGlass(root.querySelector('[data-admin-header]'));stop?.();stop=watchUpdates({scope:'admin',onChange:()=>{if(dialog.open||document.activeElement?.matches('input,select,textarea')){needRefresh=true;document.getElementById('pending-update').hidden=false;return;}return loadView();},onState:s=>{const live=document.getElementById('admin-live');if(live){live.dataset.live=s;live.textContent=s==='live'?'Pedidos e atendimentos ao vivo':s==='connecting'?'Conectando atualizações…':'Atualização automática • conexão em recuperação';}}});clearInterval(sessionTimer);sessionTimer=setInterval(()=>api('/api/admin/session').catch(error=>{if(error.status===401)login('Sua sessão terminou. Entre novamente.');}),60000);loadView();}
function login(message='',requiresMfa=mfaRequired){
 mfaRequired=requiresMfa!==false;stopAdminHeaderGlass();stop?.();stop=null;clearInterval(sessionTimer);clearAdminSession();dialog.close();detail.replaceChildren();currentQuote=currentSub=currentCustomer=null;loading=false;
 root.innerHTML='<main class="admin-access" id="admin-main"><div class="admin-brand">FINE FORM</div><h1>Seu painel.</h1><p>Entre com sua chave'+(mfaRequired?' e o código do autenticador':'')+'.</p><form id="access-form">'+field('key','Chave do painel','','password','required minlength="32" maxlength="4096" autocomplete="current-password"')+(mfaRequired?field('code','Código do autenticador','','text','required inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="one-time-code"'):'')+'<p class="system-error" id="access-error" role="alert" '+(!message?'hidden':'')+'>'+e(message)+'</p><button class="button orange" type="submit">Abrir painel ↗</button></form><p class="system-muted">Sessão de até 2 horas, encerrada após 20 minutos sem atividade no painel. Operações sensíveis pedem nova confirmação de acesso.</p><a class="underlined-link" href="../">Voltar ao site ↗</a></main>';
 document.getElementById('access-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;try{await api('/api/admin/session',{method:'POST',body:{key:form.elements.key.value,code:form.elements.code?.value||''}});form.reset();shell();}catch(error){const p=document.getElementById('access-error');if(p){p.hidden=false;p.textContent=error.message;}}finally{form.elements.key.value='';if(form.elements.code)form.elements.code.value='';button.disabled=false;}});
}
function confirmAccess(){
 if(authDialogPromise)return authDialogPromise;
 authDialogPromise=new Promise((resolve,reject)=>{
  const d=document.createElement('dialog');authDialog=d;d.id='admin-auth-dialog';d.className='dialog system-dialog';
  d.innerHTML='<form id="reauth-form"><h2>Confirme seu acesso.</h2><p>Esta operação altera ou exporta dados do painel.</p>'+field('key','Chave do painel','','password','required minlength="32" maxlength="4096" autocomplete="current-password"')+(mfaRequired?field('code','Novo código do autenticador','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"'):'')+'<p class="system-error" role="alert" hidden></p><div class="system-actions"><button type="submit" class="button orange">Confirmar acesso</button><button type="button" class="button outline" data-cancel-auth>Cancelar</button></div></form>';
  document.body.append(d);d.showModal();d.querySelector('input').focus();let done=false;
  const finish=error=>{if(done)return;done=true;d.querySelector('form').reset();d.remove();authDialog=null;authDialogPromise=null;error?reject(error):resolve();};
  d.querySelector('[data-cancel-auth]').onclick=()=>finish(new Error('Operação cancelada.'));d.addEventListener('cancel',event=>{event.preventDefault();finish(new Error('Operação cancelada.'));});
  d.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.target,button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;try{await api('/api/admin/reauth',{method:'POST',body:{key:form.elements.key.value,code:form.elements.code?.value||''}});finish();}catch(error){const el=form.querySelector('[role="alert"]');el.hidden=false;el.textContent=error.message;if(error.status===401&&error.message.includes('sessão')){finish(error);login('Sua sessão terminou. Entre novamente.');}}finally{form.elements.key.value='';if(form.elements.code)form.elements.code.value='';button.disabled=false;}};
 });return authDialogPromise;
}
setReauthenticationHandler(confirmAccess);
setSessionExpiryHandler(()=>{authDialog?.dispatchEvent(new Event('cancel',{cancelable:true}));login('Sua sessão terminou. Entre novamente.');});
async function loadView(){if(loading){needRefresh=true;return;}loading=true;const requestedTab=tab,view=document.getElementById('admin-view');if(!view){loading=false;return;}
 try{root.querySelector('.admin-shell').dataset.active=requestedTab;document.getElementById('admin-greeting').textContent=requestedTab==='dashboard'?'Olá, Mateus':'Administração';document.getElementById('view-title').textContent=titles[requestedTab];root.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===requestedTab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const more=root.querySelector('[data-action="more"]');if(['subscriptions','plates','customers','analytics','notifications','settings'].includes(requestedTab))more?.setAttribute('aria-current','page');else more?.removeAttribute('aria-current');
  if(requestedTab==='dashboard')await dashboard(view);if(requestedTab==='analytics')await analytics(view);if(requestedTab==='quotes')await quotes(view);if(requestedTab==='subscriptions')await subscriptions(view);if(requestedTab==='plates')await plates(view);if(requestedTab==='agenda')await agenda(view);if(requestedTab==='customers')await customers(view);if(requestedTab==='settings')await settings(view);if(requestedTab==='notifications')await notificationView(view,{toast});
  document.getElementById('pending-update').hidden=true;needRefresh=false;
 }catch(error){if(error.status===401){dialog.close();login('Sua sessão terminou. Entre novamente.');}else view.innerHTML='<p class="system-error" role="alert">'+e(error.message)+'</p>';}
 finally{loading=false;if(tab!==requestedTab)loadView();else openPendingNotification();}}
function quoteTable(items){return items.length?('<div class="ff-order-cards">'+items.map(q=>'<article class="ff-order-card"><div class="ff-order-card-head"><span class="ff-order-code">'+e(q.reference)+'</span>'+badge(q.status)+'</div><h3>'+e(q.name)+'</h3><p class="ff-order-vehicle">'+e(q.model)+' · '+e(q.budget.items[0]?.label||'Orientação')+'</p><div class="ff-order-card-footer"><strong>'+money(q.confirmedTotal??q.budget.total)+'</strong><button type="button" data-quote="'+e(q.id)+'">Abrir pedido ↗</button></div><button type="button" class="ff-order-card-delete" data-delete-quote="'+e(q.id)+'" aria-label="Excluir pedido '+e(q.reference)+'">Excluir pedido</button></article>').join('')+'</div>')+'<div class="admin-table-wrap ff-order-desktop"><table class="admin-table"><thead><tr><th>PEDIDO / CLIENTE</th><th>VEÍCULO / CUIDADO</th><th>VALOR</th><th>STATUS</th><th></th></tr></thead><tbody>'+items.map(q=>'<tr><td><strong>'+e(q.reference)+'</strong><small>'+e(q.name)+' · '+dateLabel(q.createdAt)+'</small></td><td>'+e(q.model)+'<small class="plate-text">'+e(registeredPlateLabel(q))+'</small><small>'+e(q.budget.items[0]?.label||'Orientação')+'</small></td><td>'+money(q.confirmedTotal??q.budget.total)+(q.budget.recurring?'<small>Inclui '+money(q.budget.recurring)+'/mês</small>':!q.budget.hasBase?'<small>Subtotal</small>':'')+'</td><td>'+badge(q.status)+'</td><td><button data-quote="'+q.id+'" type="button">Abrir ↗</button><button class="button outline system-danger" data-delete-quote="'+q.id+'" type="button" aria-label="Excluir pedido '+e(q.reference)+'">Excluir</button></td></tr>').join('')+'</tbody></table></div>':blank('Nenhum pedido nesta consulta.');}
async function dashboard(view){
 const [data,pending]=await Promise.all([api('/api/admin/dashboard'),api('/api/admin/quotes?status=pending')]);
 const metrics=[
  [Number(data.quotes.pending)||0,'Aguardando resposta','pedidos','quotes','pending'],
  [Number(data.todayVisits)||0,'Agenda de hoje','atendimentos','agenda','']
 ];
 const active=Number(data.activeSubscriptions)||0,expiring=Array.isArray(data.expiring)?data.expiring:[];
 view.innerHTML='<div class="ff-home"><div class="ff-home-overview">'+overviewHero(data.quotes)+'<div class="admin-metrics">'+metrics.map(([value,label,unit,target,status])=>'<button class="admin-metric" data-tab="'+target+'" data-status="'+status+'" type="button"><span>'+label+'</span><i class="ff-metric-icon" aria-hidden="true">'+adminNavIcon(target)+'</i><strong>'+new Intl.NumberFormat('pt-BR').format(value)+'<small>'+unit+'</small></strong></button>').join('')+'</div></div><div class="ff-home-routine"><section class="ff-week-calendar" id="ff-week-calendar" aria-label="Agenda semanal">'+weekCalendar(dashboardWeekOffset)+'</section><section class="ff-pending"><div class="ff-section-heading"><h2>Últimos pedidos</h2><button data-tab="quotes" data-status="pending" type="button">Ver todos <b aria-hidden="true">↗</b></button></div>'+
 (pending.items.length?'<div class="ff-recent-list">'+pending.items.slice(0,6).map(q=>'<button class="ff-recent-order" data-quote="'+e(q.id)+'" type="button"><i class="ff-order-icon" aria-hidden="true">'+adminNavIcon('quotes')+'</i><span><strong>'+e(q.name)+'</strong><small>'+e(q.model)+' · '+e(q.reference)+'</small></span><b class="ff-circle-action" aria-hidden="true">＋</b></button>').join('')+'</div>':'<div class="ff-empty-orders">'+adminNavIcon('quotes')+'<span><strong>Tudo em dia.</strong><small>Seus próximos pedidos aparecem aqui.</small></span></div>')+'</section><section class="ff-care-summary"><i aria-hidden="true">'+adminNavIcon('subscriptions')+'</i><button class="ff-care-details" data-tab="subscriptions" type="button"><strong>Fine Form Care</strong><small>'+active+' assinatura'+(active===1?'':'s')+' com ciclo vigente</small></button><button class="ff-circle-action" data-action="new-sub" type="button" aria-label="Cadastrar Care">＋</button></section>'+
 (expiring.length?'<section class="ff-renewals"><div class="ff-section-heading"><h2>Renovações</h2><button data-tab="subscriptions" type="button">Ver Care ↗</button></div><div class="ff-recent-list">'+expiring.map(s=>'<button class="ff-recent-order" data-sub="'+e(s.id)+'" type="button"><span><strong>'+e(s.name)+'</strong><small>Fim do ciclo: '+dateLabel(s.ends_on)+'</small></span><b class="ff-circle-action" aria-hidden="true">↗</b></button>').join('')+'</div></section>':'')+'<button class="ff-statistics-link" data-tab="analytics" type="button">'+adminNavIcon('analytics')+'Ver estatísticas dos pedidos <b aria-hidden="true">↗</b></button></div></div>';
}
async function analytics(view){
 const data=await api('/api/admin/dashboard');
 const active=Number(data.activeSubscriptions)||0,completed=Number(data.quotes.completed)||0;
 view.innerHTML='<div class="ff-statistics-view">'+overviewChart(data.quotes)+'<div class="admin-metrics"><button class="admin-metric" data-tab="subscriptions" type="button"><span>Care ativo</span><i class="ff-metric-icon" aria-hidden="true">'+adminNavIcon('subscriptions')+'</i><strong>'+active+'<small>assinaturas</small></strong></button><button class="admin-metric" data-tab="quotes" data-status="completed" type="button"><span>Concluídos</span><i class="ff-metric-icon" aria-hidden="true">'+adminNavIcon('quotes')+'</i><strong>'+completed+'<small>pedidos entregues</small></strong></button></div></div>';
}
function toolbar(type){const options=type==='quotes'?Object.entries(statusLabel):Object.entries(subLabels);return '<form class="admin-toolbar" id="filter-form"><input class="system-input" name="q" aria-label="Buscar por placa, nome ou telefone" placeholder="Placa, nome, telefone'+(type==='quotes'?' ou referência':' ou veículo')+'" value="'+e(search)+'"><select class="system-input" name="status" aria-label="Filtrar status"><option value="">Todos os status</option>'+options.map(([s,l])=>'<option value="'+s+'" '+(s===filter?'selected':'')+'>'+l+'</option>').join('')+'</select><button class="button outline" type="submit">Buscar</button>'+(type==='subscriptions'?'<button class="button orange" type="button" data-action="new-sub">Cadastrar Care ↗</button>':'')+'</form>';}
function pagination(data){return '<div class="system-pagination"><button data-action="prev" type="button" '+(!page?'disabled':'')+'>← Anterior</button><span class="system-muted">Página '+(page+1)+'</span><button data-action="next" type="button" '+(!data.hasMore?'disabled':'')+'>Próxima →</button></div>';}
async function quotes(view){let data=await api('/api/admin/quotes?'+new URLSearchParams({page,q:search,status:filter}));if(page&&!data.items.length){page--;data=await api('/api/admin/quotes?'+new URLSearchParams({page,q:search,status:filter}));}view.innerHTML=toolbar('quotes')+quoteTable(data.items)+pagination(data);}
async function subscriptions(view){const data=await api('/api/admin/subscriptions?'+new URLSearchParams({page,q:search,status:filter}));view.innerHTML=toolbar('subscriptions')+(data.items.length?'<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CLIENTE / VEÍCULO</th><th>PLANO</th><th>SALDO / CICLO</th><th>STATUS</th><th></th></tr></thead><tbody>'+data.items.map(s=>'<tr><td><strong>'+e(s.name)+'</strong><small>'+e(s.model)+'</small><small class="plate-text">'+e(registeredPlateLabel(s))+'</small></td><td>'+e(findPlan(s.planId).name)+'</td><td>'+(s.cycle?Object.entries(s.cycle.credits).filter(([,v])=>v.quota>0).map(([k,v])=>visitLabel[k]+': '+v.available+'/'+v.quota).join(' · ')+'<small>Fim: '+dateLabel(s.cycle.ends_on)+(s.cycle.expired?' · Expirado':s.cycle.notStarted?' · Futuro':'')+'</small>':'Sem ciclo')+'</td><td>'+badge(s.status)+'</td><td><button data-sub="'+s.id+'" type="button">Gerenciar ↗</button></td></tr>').join('')+'</tbody></table></div>':blank('Nenhuma assinatura nesta consulta.'))+pagination(data);}
async function plates(view){
 const [subs,orders]=await Promise.all([api('/api/admin/subscriptions?'+new URLSearchParams({page,q:search,status:filter})),api('/api/admin/quotes?'+new URLSearchParams({page,q:search}))]);
 view.innerHTML=toolbar('subscriptions')+'<h2 class="admin-section-title">Placas e assinaturas</h2>'+(subs.items.length?'<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>PLACA</th><th>CLIENTE / VEÍCULO</th><th>ASSINATURA</th><th></th></tr></thead><tbody>'+subs.items.map(s=>'<tr><td><strong class="plate-text">'+e(registeredPlateLabel(s))+'</strong></td><td>'+e(s.name)+'<small>'+e(s.model)+'</small></td><td>'+e(findPlan(s.planId).name)+'<small>'+e(subLabels[s.status])+'</small></td><td><button type="button" data-sub="'+s.id+'">'+(s.plateVerified?'Gerenciar placa':'Conferir e cadastrar')+' ↗</button></td></tr>').join('')+'</tbody></table></div>':blank('Nenhuma assinatura nesta consulta.'))+'<h2 class="admin-section-title system-history-title">Pedidos e orçamentos</h2>'+quoteTable(orders.items)+pagination({hasMore:subs.hasMore||orders.hasMore});
}
async function agenda(view){const data=await api('/api/admin/agenda?date='+encodeURIComponent(agendaDate));const entries=[...data.quotes.map(q=>({...q,isQuote:true})),...data.visits].sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));view.innerHTML='<form class="admin-toolbar" id="agenda-form"><input class="system-input" type="date" name="date" aria-label="Dia da agenda" value="'+e(agendaDate)+'" required><button class="button outline" type="submit">Consultar dia</button></form>'+(entries.length?'<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>HORÁRIO</th><th>CLIENTE / VEÍCULO</th><th>CUIDADO</th><th>STATUS</th><th></th></tr></thead><tbody>'+entries.map(v=>'<tr><td><strong>'+e(v.time||'A combinar')+'</strong></td><td>'+e(v.name)+'<small>'+e(v.model)+'</small><small class="plate-text">'+e(plateLabel(v.plate))+'</small></td><td>'+e(v.isQuote?v.reference:'Care · '+visitLabel[v.kind])+'</td><td>'+badge(v.status,v.isQuote?statusLabel[v.status]:visitStates[v.status])+'</td><td><button '+(v.isQuote?'data-quote="'+v.id+'"':'data-sub="'+v.subscriptionId+'"')+' type="button">Abrir ↗</button></td></tr>').join('')+'</tbody></table></div>':blank('Nenhum atendimento confirmado para este dia.'))+'<p class="system-muted">A agenda exibe pedidos aceitos e visitas Care reservadas. Pedidos sem data confirmada ficam na aba Pedidos. Horários não são bloqueados automaticamente: considere a duração de cada cuidado antes de aceitar.</p>';}
async function customers(view){const data=await api('/api/admin/customers?q='+encodeURIComponent(search));view.innerHTML='<form class="admin-toolbar" id="customers-form"><input class="system-input" name="q" value="'+e(search)+'" aria-label="Buscar clientes" placeholder="Início do nome ou telefone"><button class="button outline" type="submit">Buscar</button></form>'+(data.items.length?'<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>CLIENTE</th><th>CONTATO</th><th>PRIMEIRO VEÍCULO</th><th>PLANOS</th><th></th></tr></thead><tbody>'+data.items.map(c=>'<tr><td>'+e(c.name)+'</td><td><a href="https://wa.me/'+e(c.phone)+'" target="_blank" rel="noopener noreferrer">'+e(c.phone)+' ↗</a></td><td>'+e(c.model)+'</td><td>'+c.plans+'</td><td><button class="button outline system-danger" data-delete-customer="'+e(c.id)+'" type="button" aria-label="Excluir cliente '+e(c.name)+'">Excluir cliente</button></td></tr>').join('')+'</tbody></table></div>':blank('Clientes entram aqui quando um pedido é aceito ou um plano é cadastrado.'))+'<p class="system-muted">Até 100 clientes nesta consulta. Cada assinatura guarda o seu próprio veículo. Use a busca para localizar registros mais antigos.</p>';}
async function settings(view){view.innerHTML='<section class="system-card admin-business-settings" id="business-settings"></section><section class="system-card admin-backup"><h2>Backup</h2><p class="system-muted">O arquivo contém dados pessoais. Armazene com segurança.</p><div class="system-actions"><button class="button orange" data-action="backup" type="button">Exportar dados JSON ↓</button></div></section>';await mountBusinessSettings(view.querySelector('#business-settings'),{toast});}
function vehicleRegistration(q){
 if(q.kind==='subscription_visit'||q.subscriptionId)return '<div class="system-note">Veículo vinculado ao Care. Confira a placa física antes de iniciar ou concluir esta visita.</div>';
 if(['completed','declined','cancelled'].includes(q.status))return '';
 return '<section class="system-card"><h3>'+ (q.plateVerified?'Veículo cadastrado neste pedido.':'Receber veículo e cadastrar placa.')+'</h3><p class="system-muted">Você pode aceitar e agendar o orçamento antes da chegada. Quando o veículo estiver aqui, confira a placa e registre abaixo. O mesmo link do cliente será atualizado.</p><form id="register-vehicle">'+field('plate','Placa que conferi no veículo',q.plate||'','text',plateInputAttrs)+area('reason',q.plateVerified?'Motivo da correção, se mudar a placa':'Observação do cadastro (opcional)','',300)+'<label class="system-check"><input name="confirm" type="checkbox" required><span>Conferi esta placa pessoalmente no veículo.</span></label><button class="button orange" type="submit">'+(q.plateVerified?'Salvar conferência':'Cadastrar veículo neste pedido')+'</button></form></section>';
}
function budgetDetails(q){const b=q.budget;return '<div class="system-list">'+b.items.map(item=>'<div class="system-row"><span>'+e(item.label)+'</span><strong>'+money(item.price)+'</strong></div>').join('')+(b.discount?'<div class="system-row"><span>Etapas em comum</span><strong>−'+money(b.discount)+'</strong></div>':'')+'<div class="system-row"><strong>'+(!b.hasBase&&q.confirmedTotal===null?'Subtotal':'Total')+'</strong><strong>'+money(q.confirmedTotal??b.total)+'</strong></div></div>'+(b.recurring?'<p class="system-muted">Mensalidade: '+money(b.recurring)+'. Adicionais desta visita: '+money(b.additional)+'.</p>':'');}

function quoteMessage(q,status,template=''){
 const name=(q.name||'cliente').trim().split(/\s+/)[0],ref=q.reference,vehicle=q.model||'veículo';
 const date=q.scheduledDate||q.preferredDate,time=q.scheduledTime||q.preferredTime;
 const schedule=q.scheduledDate?'para '+dateLabel(q.scheduledDate)+(q.scheduledTime?' às '+q.scheduledTime:' (horário a confirmar)'):'';
 switch(template||status){
  case 'pending':return 'Olá, '+name+'! Recebemos seu pedido '+ref+' na Fine Form. Vamos avaliar e confirmar os próximos passos.';
  case 'accepted':return schedule?'Olá, '+name+'! Seu pedido '+ref+' foi aceito. Atendimento agendado '+schedule+'. Acompanhe pelo seu link privado.':'Olá, '+name+'! Seu pedido '+ref+' foi aceito. Vamos confirmar a data e o horário do atendimento. Acompanhe pelo seu link privado.';
  case 'in_progress':return 'Olá, '+name+'! Seu '+vehicle+' está em atendimento na Fine Form. Avisaremos sobre a próxima etapa.';
  case 'preparation':return 'Olá, '+name+'! Seu '+vehicle+' entrou na fase de preparação e revisão final. Avisaremos quando estiver pronto para retirada.';
  case 'ready':return 'Olá, '+name+'! Seu veículo está pronto para retirada na Fine Form. Entre em contato para combinar a entrega.';
  case 'completed':return 'Olá, '+name+'! Seu veículo foi entregue. Obrigado pela confiança! O histórico permanece disponível pelo seu link privado.';
  case 'declined':return 'Olá, '+name+'! Não foi possível aceitar o pedido '+ref+' nas condições solicitadas. Fale conosco para avaliar alternativas.';
  case 'cancelled':return 'Olá, '+name+'! Seu pedido '+ref+' foi cancelado. Entre em contato para verificar um novo atendimento.';
  default:return q.message||'';
 }
}
function quoteWhatsApp(q,message){return 'https://wa.me/'+encodeURIComponent(q.phone)+'?text='+encodeURIComponent(message);}
function quoteQuickActions(q){
 const available=transitions[q.status]||[],active=available.filter(s=>!['declined','cancelled'].includes(s));
 const needsPlate=!q.plateVerified&&q.kind!=='subscription_visit'&&active.some(s=>['in_progress','ready','completed'].includes(s));
 const action=s=>'<button type="button" class="ff-quick-status" data-quick-quote-status="'+e(s)+'" '+(needsPlate&&['in_progress','ready','completed'].includes(s)?'disabled title="Conferir placa do veículo antes"':'')+'>'+e(statusLabel[s])+'</button>';
 const preview=active.length?quoteMessage(q,active[0]):(q.message||'Este pedido já foi encerrado.');
 return '<section class="ff-quote-quick" aria-label="Atualizar etapa do atendimento"><div class="ff-quote-quick-title"><h3>Etapa do atendimento</h3><span>Atualização em um toque</span></div><p class="ff-quote-intro">Selecione a próxima etapa. A mensagem correspondente será publicada automaticamente no acompanhamento do cliente.</p><div class="ff-quick-statuses">'+(active.length?active.map(action).join(''):'<p class="system-muted">Pedido encerrado.</p>')+(q.status==='in_progress'?'<button class="ff-quick-status" type="button" data-quick-quote-preparation>Em preparação · avisar</button>':'')+'</div>'+(needsPlate?'<p class="ff-quick-warning">Para avançar, confirme a placa do veículo. <button type="button" data-quote-jump="vehicle">Conferir placa</button></p>':'')+(available.some(s=>['cancelled','declined'].includes(s))?'<details class="ff-quick-secondary"><summary>Recusar ou cancelar</summary><div class="ff-quick-statuses">'+available.filter(s=>['cancelled','declined'].includes(s)).map(action).join('')+'</div></details>':'')+'<div class="ff-quick-preview"><span>Mensagem automática para o cliente</span><p id="ff-quick-preview" role="status">'+e(preview)+'</p></div></section>';
}
async function openQuote(id){const data=await api('/api/admin/quotes/'+id);currentQuote=data.quote;const q=currentQuote;currentSub=null;const vehicleSection=vehicleRegistration(q);modal('<div class="ff-quote-view"><header class="ff-quote-head"><span class="ff-quote-kicker">DETALHES DO PEDIDO</span><h2 tabindex="-1">'+e(q.reference)+'</h2>'+badge(q.status)+'</header>'+quoteQuickActions(q)+'<section class="ff-quote-facts" aria-label="Resumo do pedido"><div class="ff-quote-fact ff-quote-client"><span>Cliente</span><strong>'+e(q.name)+'</strong><a href="https://wa.me/'+e(q.phone)+'" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a><small>'+e(q.phone)+'</small></div><div class="ff-quote-fact"><span>Veículo</span><strong>'+e(q.model)+'</strong><small class="plate-text">'+e(registeredPlateLabel(q))+'</small></div><div class="ff-quote-fact"><span>Preferência</span><strong>'+dateLabel(q.preferredDate)+(q.preferredTime?' · '+e(q.preferredTime):'')+'</strong></div>'+(q.notes?'<div class="ff-quote-fact ff-quote-notes"><span>Observações do cliente</span><p>'+e(q.notes)+'</p></div>':'')+'</section><details class="ff-quote-services"><summary><span>Serviços e valores</span><strong>'+money(q.confirmedTotal??q.budget.total)+'</strong></summary>'+budgetDetails(q)+'</details>'+(vehicleSection?'<details id="ff-quote-vehicle" class="ff-quote-fold"><summary>Cadastro e conferência do veículo</summary>'+vehicleSection+'</details>':'')+'<details id="ff-quote-edit" class="ff-quote-fold"><summary>Agendamento e mensagem personalizada</summary><form id="quote-edit"><h4 class="ff-quote-form-heading">1. Status e agendamento</h4>'+select('status','Status',[[q.status,statusLabel[q.status]],...transitions[q.status].map(s=>[s,statusLabel[s]])],q.status)+'<p class="system-muted">Marque “Retirado / entregue” somente após entregar o veículo. Nesse momento, o cliente pode avaliar e recebe um convite se ativou as notificações.</p>'+'<div class="system-grid">'+field('scheduledDate','Data confirmada',q.scheduledDate||q.preferredDate||'','date')+field('scheduledTime','Horário confirmado',q.scheduledTime||q.preferredTime||'','time')+'</div>'+((q.kind==='guidance'||q.kind==='single')?field('confirmedTotal','Valor completo confirmado (R$)',q.confirmedTotal??'','number','min="0" max="100000" step="0.01"')+'<p class="system-muted">Orientação exige o valor completo para aceitar. Deixe vazio para manter o preço do catálogo nos outros pedidos.</p>':'')+(q.kind==='subscription_visit'?field('checkedPlate','Placa conferida no veículo (para iniciar, liberar ou concluir)','','text',plateInputAttrs.replace('required ','') )+'<p class="system-muted">Confira a placa física. O Care atende apenas a placa vinculada. Este campo não altera o cadastro.</p>':'')+'<h4 class="ff-quote-form-heading">2. Comunicação com o cliente</h4><p class="ff-quote-form-hint">A mensagem é preenchida automaticamente ao alterar o status. Edite apenas se quiser personalizar.</p><label class="system-field"><span>Preencher mensagem automaticamente</span><select id="ff-quote-template"><option value="">Selecione um modelo</option>'+[['pending','Recebido'],['accepted','Aceito'],['in_progress','Em cuidado'],['preparation','Em preparação'],['ready','Pronto para retirada'],['completed','Retirado / entregue'],['declined','Recusado'],['cancelled','Cancelado']].map(([v,l])=>'<option value="'+v+'">'+l+'</option>').join('')+'</select></label>'+area('message','Mensagem para o cliente',q.message)+'<a id="ff-quote-whatsapp" class="button outline ff-quote-whatsapp" target="_blank" rel="noopener noreferrer" href="'+e(quoteWhatsApp(q,q.message||quoteMessage(q,q.status)))+'">Abrir mensagem no WhatsApp ↗</a><h4 class="ff-quote-form-heading">3. Anotações internas</h4>'+area('internalNote','Anotação interna · apenas no painel',q.internalNote)+'<button class="button orange" type="submit">Salvar atualização ↗</button></form></details>'+(q.kind==='plan'&&q.status==='accepted'&&q.plateVerified&&!q.subscriptionId?'<hr class="system-divider"><h3>Ativar este Care.</h3><form id="activate-plan">'+('<p>Veículo conferido. Assinatura exclusiva da placa <strong class="plate-text">'+e(q.plate)+'</strong>.</p>')+field('startsOn','Início do ciclo',todaySP(),'date','required')+paid+'<button class="button orange" type="submit">Ativar após pagamento</button></form>':'')+(q.subscriptionId?'<div class="system-actions"><button class="button outline" data-sub="'+q.subscriptionId+'" type="button">Gerenciar assinatura ↗</button></div>':'')+'<div class="ff-quote-security"><button class="button outline" data-action="reload-quote" type="button">Atualizar informações (manter link)</button><details class="ff-quote-fold"><summary>Link privado e opções administrativas</summary><p class="system-muted">Recarregar ou salvar o pedido mantém o link original. Gere outro somente para revogar o acesso anterior.</p><div class="system-actions"><button class="button outline system-danger" data-action="quote-link" type="button">Revogar link atual e gerar outro</button><button class="button outline system-danger" data-delete-quote="'+q.id+'" type="button">Excluir pedido</button></div></details></div><details class="ff-quote-fold ff-quote-history"><summary>Histórico do pedido</summary><ol class="system-timeline">'+data.events.map(v=>'<li><strong>'+e(statusLabel[v.status])+'</strong><p>'+e(v.message)+'</p><time>'+e(new Date(v.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))+'</time></li>').join('')+'</ol></details></div>');
 mountQuoteLocation(detail,q,{toast,onSaved:async()=>{await openQuote(q.id);loadView();}});
 detail.querySelectorAll('[data-quote-jump]').forEach(button=>button.addEventListener('click',()=>{
  const section=detail.querySelector(button.dataset.quoteJump==='vehicle'?'#ff-quote-vehicle':'#ff-quote-edit');
  if(!section)return;
  section.open=true;section.scrollIntoView({block:'start'});
  section.querySelector('input,select,textarea')?.focus({preventScroll:true});
 }));

 const edit=document.getElementById('quote-edit'),statusInput=edit?.elements.status,messageInput=edit?.elements.message,templateInput=document.getElementById('ff-quote-template'),whatsApp=document.getElementById('ff-quote-whatsapp');
 const updateWhatsApp=()=>{if(whatsApp&&messageInput)whatsApp.href=quoteWhatsApp(q,messageInput.value||quoteMessage(q,statusInput?.value||q.status));};
 statusInput?.addEventListener('change',()=>{messageInput.value=quoteMessage(q,statusInput.value);if(templateInput)templateInput.value=statusInput.value;updateWhatsApp();});
 templateInput?.addEventListener('change',()=>{if(templateInput.value)messageInput.value=quoteMessage(q,statusInput.value,templateInput.value);updateWhatsApp();});
 messageInput?.addEventListener('input',updateWhatsApp);
 const previewNode=detail.querySelector('#ff-quick-preview');
  const initialPreview=previewNode?.textContent||'';
  detail.querySelectorAll('[data-quick-quote-status],[data-quick-quote-preparation]').forEach(button=>{
   const previewText=()=>quoteMessage(q,button.dataset.quickQuoteStatus||q.status,button.hasAttribute('data-quick-quote-preparation')?'preparation':'');
   button.addEventListener('pointerenter',()=>{if(previewNode)previewNode.textContent=previewText();});
   button.addEventListener('focus',()=>{if(previewNode)previewNode.textContent=previewText();});
   button.addEventListener('pointerleave',()=>{if(previewNode)previewNode.textContent=initialPreview;});
   button.addEventListener('blur',()=>{if(previewNode)previewNode.textContent=initialPreview;});
  });
  detail.querySelectorAll('[data-quick-quote-status],[data-quick-quote-preparation]').forEach(button=>button.addEventListener('click',async()=>{
  if(button.disabled||detail.dataset.quickSaving)return;
  const preparing=button.hasAttribute('data-quick-quote-preparation'),status=preparing?q.status:button.dataset.quickQuoteStatus;
  if(['completed','declined','cancelled'].includes(status)&&!confirm(status==='completed'?'O veículo já foi entregue ao cliente?':'Confirmar '+statusLabel[status].toLowerCase()+' deste pedido?'))return;
  if(q.kind!=='subscription_visit'&&!q.plateVerified&&['in_progress','ready','completed'].includes(status)){
   const section=detail.querySelector('#ff-quote-vehicle');if(section){section.open=true;section.scrollIntoView({block:'start'});}modalError(new Error('Confirme e salve a placa antes de alterar para '+statusLabel[status]+'.'));return;
  }
  if(q.kind==='subscription_visit'&&['in_progress','ready','completed'].includes(status)){
   const section=detail.querySelector('#ff-quote-edit');if(section){section.open=true;section.scrollIntoView({block:'start'});}modalError(new Error('Em visitas Care, informe a placa conferida no formulário para avançar.'));return;
  }
  detail.dataset.quickSaving='1';const buttons=[...detail.querySelectorAll('[data-quick-quote-status],[data-quick-quote-preparation]')];buttons.forEach(b=>b.disabled=true);
  try{await api('/api/admin/quotes/'+q.id,{method:'PATCH',body:{version:q.version,status,message:quoteMessage(q,status,preparing?'preparation':'')}});
   toast('Etapa e mensagem publicadas no acompanhamento. O link privado foi preservado.');await openQuote(q.id);loadView();
  }catch(error){modalError(error);if(error.status===409)toast('O pedido mudou. Recarregue as informações e tente novamente.');}
  finally{delete detail.dataset.quickSaving;buttons.forEach(b=>b.disabled=false);}
 }));
 document.getElementById('register-vehicle')?.addEventListener('submit',event=>withForm(event,async form=>{await api('/api/admin/quotes/'+q.id+'/plate',{method:'PATCH',body:{version:q.version,plate:form.elements.plate.value,reason:form.elements.reason.value,confirm:form.elements.confirm.checked}});toast('Veículo cadastrado. O link do cliente já mostra a placa conferida.');await openQuote(q.id);loadView();}));
 document.getElementById('quote-edit').onsubmit=event=>withForm(event,async form=>{const body=Object.fromEntries(new FormData(form));body.version=q.version;if(form.elements.confirmedTotal)body.confirmedTotal=body.confirmedTotal===''?null:Number(body.confirmedTotal);await api('/api/admin/quotes/'+q.id,{method:'PATCH',body});toast('Pedido atualizado. O cliente recebe a atualização na página.');await openQuote(q.id);loadView();});
 document.getElementById('activate-plan')?.addEventListener('submit',event=>withForm(event,async form=>{const result=await api('/api/admin/subscriptions',{method:'POST',body:{quoteId:q.id,paidConfirmed:form.elements.paidConfirmed.checked,startsOn:form.elements.startsOn.value}});await openSub(result.subscription.id);showLink(result.subscription.id,result.portalToken,'assinatura');loadView();}));
}
async function withForm(event,action){event.preventDefault();const form=event.target;if(form.dataset.busy)return;form.dataset.busy='true';form.inert=true;const button=form.querySelector('[type="submit"]');button.disabled=true;const error=document.getElementById('dialog-error');if(error)error.hidden=true;try{await action(form);}catch(err){modalError(err);}finally{delete form.dataset.busy;form.inert=false;button.disabled=false;}}
function showLink(id,token,path){const link=trackingUrl(id,token,path);let box=document.getElementById('generated-link');if(!box){box=document.createElement('section');box.className='system-success';box.id='generated-link';detail.prepend(box);}box.innerHTML='<strong>Link privado do cliente</strong><p>Copie e envie ao cliente pelo contato conferido. Guarde este link antes de fechar.</p><a class="tracking-link" href="'+e(link)+'" target="_blank" rel="noopener noreferrer">'+e(link)+'</a><div class="system-actions"><button class="button outline" id="copy-generated-link" type="button">Copiar link</button></div>';document.getElementById('copy-generated-link').onclick=()=>copyText(link).then(()=>toast('Link copiado.')).catch(modalError);box.scrollIntoView({block:'nearest'});}
function manualSub(){currentSub=null;currentQuote=null;modal('<h2 tabindex="-1">Cadastrar Fine Form Care.</h2><p class="system-muted">Confira o veículo presente e cadastre a placa. O Care só é ativado após essa conferência e o pagamento.</p><form id="manual-sub">'+field('name','Cliente','','text','required maxlength="80"')+field('phone','WhatsApp com DDD','','tel','required maxlength="20"')+field('model','Marca e modelo do veículo','','text','required maxlength="80"')+field('plate','Placa que conferi no veículo','','text',plateInputAttrs)+'<label class="system-check"><input name="confirmVehicle" type="checkbox" required><span>Conferi esta placa pessoalmente no veículo.</span></label>'+select('planId','Plano',plans.map(p=>[p.id,p.name+' · '+money(p.price)+'/mês']),plans[0].id)+field('startsOn','Início do ciclo',todaySP(),'date','required')+paid+'<button class="button orange" type="submit">Ativar assinatura ↗</button></form>');document.getElementById('manual-sub').onsubmit=event=>withForm(event,async form=>{const body=Object.fromEntries(new FormData(form));body.paidConfirmed=form.elements.paidConfirmed.checked;body.confirmVehicle=form.elements.confirmVehicle.checked;const result=await api('/api/admin/subscriptions',{method:'POST',body});await openSub(result.subscription.id);showLink(result.subscription.id,result.portalToken,'assinatura');loadView();});}
async function openSub(id){const data=await api('/api/admin/subscriptions/'+id);const s=data.subscription,c=s.cycle,p=findPlan(s.planId);currentSub=s;currentQuote=null;const latest=s.history[0],nextStart=latest?.end>todaySP()?latest.end:todaySP();modal('<h2 tabindex="-1">'+e(p.name)+' · '+e(s.name)+'</h2>'+badge(s.status)+'<p>'+e(s.model)+' · <strong class="plate-text">'+e(registeredPlateLabel(s))+'</strong> · <a href="https://wa.me/'+e(s.phone)+'" target="_blank" rel="noopener noreferrer">'+e(s.phone)+' ↗</a></p>'+(!s.plateVerified?'<div class="system-note">Cadastre a placa em “Placa da assinatura”, nesta página, para liberar novas solicitações, registros de lavagem e renovações. Seu saldo e histórico estão preservados.</div>':'')+'<div class="system-note">'+period(c)+(c?'<br>'+money(c.price_cents/100)+' · '+(c.paid?'Pago':'Pendente')+(c.expired?' · Expirado':c.notStarted?' · Futuro':''):'')+'</div><div class="credit-grid">'+(c?Object.entries(c.credits).filter(([,v])=>v.quota>0).map(([k,v])=>'<div class="credit-box"><h3>'+visitLabel[k]+'</h3><strong>'+v.available+'</strong><span> / '+v.quota+' disponíveis</span><p>'+v.done+' concluída(s) · '+v.reserved+' reservada(s)</p></div>').join(''):'')+'</div><p class="system-muted">Pausar não estende o ciclo. Saldo não acumula entre ciclos. Uma visita aceita reserva saldo; uma visita concluída registra uso.</p><h3>Visitas do ciclo consultado.</h3>'+(s.visits.length?'<div class="system-list">'+s.visits.map(v=>'<div class="system-row"><span><strong>'+visitLabel[v.kind]+'</strong><small>'+dateLabel(v.date)+(v.time?' · '+e(v.time):'')+' · '+e(plateLabel(v.plate))+' · '+visitStates[v.status]+'</small></span><div>'+(['scheduled','in_progress'].includes(v.status)?'<button class="button outline" data-finish-visit="'+v.id+'" data-version="'+v.version+'" type="button">Concluir</button>':'')+(v.status!=='cancelled'?'<button class="button outline system-danger" data-undo-visit="'+v.id+'" data-version="'+v.version+'" type="button">Desfazer</button>':'')+'</div></div>').join('')+'</div>':'<p class="system-muted">Sem visitas neste ciclo.</p>')+(s.status==='active'&&s.plateVerified&&c&&!c.expired&&!c.notStarted?'<hr class="system-divider"><h3>Registrar lavagem.</h3><form id="record-visit">'+field('checkedPlate','Placa conferida no veículo (obrigatória para concluir)','','text',plateInputAttrs.replace('required ',''))+select('kind','Lavagem',Object.entries(c.credits).filter(([,v])=>v.quota>0).map(([k,v])=>[k,visitLabel[k]+' · '+v.available+' disponível(is)']))+select('status','Registro',[['completed','Concluída'],['scheduled','Agendada']],'completed')+'<div class="system-grid">'+field('date','Data',todaySP(),'date','required')+field('time','Horário (opcional)','','time')+'</div>'+area('note','Observação interna','',300)+'<button class="button orange" type="submit">Registrar no ciclo</button></form>':'')+(s.status==='active'&&s.plateVerified?'<hr class="system-divider"><h3>Renovar Care.</h3><p class="system-muted">Renovação cria um novo ciclo, com saldo novo. Ciclos não podem se sobrepor. Um ciclo futuro pago não substitui o saldo vigente.</p><form id="renew-care">'+field('startsOn','Início do próximo ciclo',nextStart,'date','required')+paid+'<button class="button orange" type="submit">Confirmar pagamento e renovar</button></form>':'')+'<hr class="system-divider"><h3>Placa da assinatura.</h3><p class="system-muted">O Care é exclusivo da placa cadastrada. O cliente não pode trocar o veículo pelo portal. Correções precisam de motivo e ficam no histórico interno.</p>'+(s.status!=='cancelled'?'<form id="subscription-plate">'+field('plate',s.plateVerified?'Corrigir placa cadastrada':'Placa que conferi pessoalmente',s.plate||'','text',plateInputAttrs)+area('reason','Motivo do cadastro ou da correção','',300)+'<label class="system-check"><input name="confirm" type="checkbox" required><span>Conferi a placa no veículo e autorizo este vínculo.</span></label><button class="button orange" type="submit">Salvar placa</button></form><hr class="system-divider">':'')+'<h3>Gestão do plano.</h3><div class="system-actions">'+(s.status!=='cancelled'?'<button class="button outline" data-sub-status="'+(s.status==='active'?'paused':'active')+'" type="button">'+(s.status==='active'?'Pausar plano':'Reativar plano')+'</button><button class="button outline system-danger" data-sub-status="cancelled" type="button">Cancelar plano</button>':'<button class="button outline system-danger" data-action="delete-sub" type="button">Excluir assinatura definitivamente</button>')+'<button class="button outline" data-action="portal-link" type="button">Reemitir link do cliente</button><button class="button outline" data-action="reload-sub" type="button">Recarregar</button></div><h3 class="system-history-title">Histórico de ciclos.</h3><div class="system-list">'+s.history.map(h=>'<div class="system-row"><span>'+dateLabel(h.start)+' → '+dateLabel(h.end)+'<small>Fim exclusivo · '+(h.paid?'Pago':'Pendente')+'<br>'+Object.entries(h.credits).filter(([,v])=>v.quota>0).map(([k,v])=>visitLabel[k]+': '+v.done+'/'+v.quota+' realizada(s)').join(' · ')+'</small></span><strong>'+money(h.price)+'</strong></div>').join('')+'</div>');
 document.getElementById('subscription-plate')?.addEventListener('submit',event=>withForm(event,async form=>{await api('/api/admin/subscriptions/'+id+'/plate',{method:'PATCH',body:{version:s.version,plate:form.elements.plate.value,reason:form.elements.reason.value,confirm:form.elements.confirm.checked}});toast('Placa salva. O histórico das visitas foi preservado.');await openSub(id);loadView();}));
 if(s.visitHistory.length)detail.insertAdjacentHTML('beforeend','<hr class="system-divider"><details><summary>Lavagens de ciclos anteriores</summary><div class="system-list">'+s.visitHistory.map(v=>'<div class="system-row"><span>'+visitLabel[v.kind]+'<small>'+dateLabel(v.date)+(v.time?' · '+e(v.time):'')+' · '+e(plateLabel(v.plate))+'</small></span><span>'+visitStates[v.status]+'</span></div>').join('')+'</div></details>');
 document.getElementById('record-visit')?.addEventListener('submit',event=>withForm(event,async form=>{const body=Object.fromEntries(new FormData(form));body.cycleId=c.id;form.dataset.operationId ||= crypto.randomUUID();body.operationId=form.dataset.operationId;await api('/api/admin/subscriptions/'+id+'/visits',{method:'POST',body});toast('Lavagem registrada. Saldo atualizado.');await openSub(id);loadView();}));
 document.getElementById('renew-care')?.addEventListener('submit',event=>withForm(event,async form=>{await api('/api/admin/subscriptions/'+id+'/renew',{method:'POST',body:{version:s.version,startsOn:form.elements.startsOn.value,paidConfirmed:form.elements.paidConfirmed.checked}});toast('Novo ciclo pago registrado.');await openSub(id);loadView();}));
}
async function removeQuote(id,button){
 button.disabled=true;button.setAttribute('aria-busy','true');
 try{
  const q=dialog.open&&currentQuote?.id===id?currentQuote:(await api('/api/admin/quotes/'+id)).quote;
  const warning=q.kind==='subscription_visit'?' A visita vinculada também será apagada e o saldo da lavagem será devolvido.':q.subscriptionId?' A assinatura permanecerá cadastrada; o link deste pedido deixará de abrir o Care.':'';
  if(!confirm('Excluir definitivamente o pedido '+q.reference+' de '+q.name+'? O pedido e seu histórico serão apagados, e o link de acompanhamento deixará de funcionar.'+warning))return;
  await api('/api/admin/quotes/'+id,{method:'DELETE',body:{version:q.version,confirm:true}});if(dialog.open&&currentQuote?.id===id){currentQuote=null;dialog.close();}await loadView();toast('Pedido excluído.');
 }finally{button.disabled=false;button.removeAttribute('aria-busy');}
}
async function confirmCustomerRemoval(id){
 const data=await api('/api/admin/customers/'+id),c=data.customer,n=data.counts;currentQuote=null;currentSub=null;
 modal('<h2 tabindex="-1">Excluir cliente.</h2><p><strong>'+e(c.name)+'</strong><br>'+e(c.phone)+'</p><p>Esta exclusão é definitiva. Também serão apagados os registros vinculados:</p><ul><li>'+n.quotes+' pedido(s) e seus históricos</li><li>'+n.subscriptions+' assinatura(s)</li><li>'+n.cycles+' ciclo(s) de assinatura</li><li>'+n.visits+' registro(s) de lavagem</li></ul><p>Os links destes pedidos e assinaturas deixarão de funcionar.</p><div class="system-actions"><button class="button outline" data-close-dialog type="button">Manter cliente</button><button class="button outline system-danger" data-action="delete-customer" type="button">Excluir cliente e registros</button></div>');currentCustomer=data;
}
async function undoVisit(id,version){const subId=currentSub.id;const reason=prompt('Motivo para desfazer este registro? O saldo da lavagem será liberado.');if(!reason)return;await api('/api/admin/visits/'+id,{method:'PATCH',body:{version,status:'cancelled',reason}});await openSub(subId);loadView();toast('Registro desfeito com motivo no histórico.');}
async function action(name){if(name==='header-more'||name==='more'){const menu=document.getElementById('admin-more-menu');if(!menu)return;if(menu.hidden){menu.hidden=false;root.querySelector('[data-action="more"]')?.setAttribute('aria-expanded','true');root.querySelector('[data-action="header-more"]')?.setAttribute('aria-expanded',String(name==='header-more'));menu.querySelector('[data-tab]')?.focus();}else closeMore(true);return;}if(name==='close-more'){closeMore(true);return;}if(name==='logout'){await api('/api/admin/session',{method:'DELETE'});dialog.close();login();}if(name==='refresh'){if(dialog.open){toast('Feche ou recarregue o registro para atualizar a edição.');return;}await loadView();}if(name==='new-sub')manualSub();if(name==='prev'){page=Math.max(0,page-1);await loadView();}if(name==='next'){page++;await loadView();}if(name==='reload-quote')await openQuote(currentQuote.id);if(name==='reload-sub')await openSub(currentSub.id);
 if(name==='quote-link'){if(!confirm('ATENÇÃO: o link antigo deixará de funcionar para o cliente. Tem certeza de que deseja revogar e gerar outro?'))return;const id=currentQuote.id,result=await api('/api/admin/quotes/'+id+'/link',{method:'POST',body:{rotate:true,version:currentQuote.version}});await openQuote(id);showLink(id,result.trackingToken,'acompanhar');}
 if(name==='portal-link'){if(!confirm('Reemitir o link do Care? O link anterior do portal deixará de funcionar. O pedido de origem continua válido.'))return;const id=currentSub.id,result=await api('/api/admin/subscriptions/'+id+'/portal',{method:'POST',body:{}});await openSub(id);showLink(id,result.portalToken,'assinatura');}
 if(name==='delete-sub'){const s=currentSub;if(!confirm('Excluir definitivamente esta assinatura e suas visitas? Exporte um backup antes. Os pedidos e o cadastro do cliente permanecem.'))return;await api('/api/admin/subscriptions/'+s.id,{method:'DELETE',body:{version:s.version,confirm:true}});dialog.close();toast('Assinatura excluída.');loadView();}
 if(name==='delete-customer'){const c=currentCustomer;if(!c)return;const button=detail.querySelector('[data-action="delete-customer"]');if(button.disabled)return;button.disabled=true;button.setAttribute('aria-busy','true');try{await api('/api/admin/customers/'+c.customer.id,{method:'DELETE',body:{confirm:true,snapshot:c.snapshot}});currentCustomer=null;dialog.close();await loadView();toast('Cliente e registros vinculados excluídos.');}catch(error){if(error.status===409){await confirmCustomerRemoval(c.customer.id);}throw error;}finally{button.disabled=false;button.removeAttribute('aria-busy');}}
 if(name==='backup'){const data=await api('/api/admin/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='fine-form-backup-'+todaySP()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup solicitado. Guarde-o em local privado.');}}
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!event.target.closest('#admin-more-menu')&&!['more','header-more'].includes(button?.dataset.action))closeMore();if(!button||button.disabled)return;try{
 if(button.dataset.week){dashboardWeekOffset+=Number(button.dataset.week);const calendar=document.getElementById('ff-week-calendar');if(calendar)calendar.innerHTML=weekCalendar(dashboardWeekOffset);}
 else if(button.dataset.agendaDate){closeMore();agendaDate=button.dataset.agendaDate;tab='agenda';page=0;search='';filter='';await loadView();}
 else if(button.dataset.tab){closeMore();tab=button.dataset.tab;page=0;search='';filter=button.dataset.status||'';const globalSearch=document.getElementById('admin-search');if(globalSearch)globalSearch.elements.q.value='';await loadView();if(button.closest('.admin-nav,.admin-mobile-nav,.admin-more-menu'))document.getElementById('admin-main')?.scrollIntoView({block:'start',behavior:'instant'});}
 else if(button.dataset.deleteQuote)await removeQuote(button.dataset.deleteQuote,button);
 else if(button.dataset.deleteCustomer)await confirmCustomerRemoval(button.dataset.deleteCustomer);
 else if(button.dataset.quote)await openQuote(button.dataset.quote);
 else if(button.dataset.sub)await openSub(button.dataset.sub);
 else if(button.dataset.action)await action(button.dataset.action);
 else if(button.dataset.subStatus){const s=currentSub,status=button.dataset.subStatus;if(status==='cancelled'&&!confirm('Cancelar este plano? O histórico permanece. Não será renovado automaticamente.'))return;await api('/api/admin/subscriptions/'+s.id,{method:'PATCH',body:{version:s.version,status}});await openSub(s.id);loadView();toast('Status do Care atualizado.');}
 else if(button.dataset.finishVisit){if(!confirm('Confirmar que essa lavagem foi realizada?'))return;const checkedPlate=prompt('Digite a placa que você conferiu no veículo. O Care é exclusivo da placa cadastrada.');if(checkedPlate===null)return;const id=currentSub.id;await api('/api/admin/visits/'+button.dataset.finishVisit,{method:'PATCH',body:{version:Number(button.dataset.version),status:'completed',checkedPlate}});await openSub(id);loadView();toast('Lavagem concluída.');}
 else if(button.dataset.undoVisit)await undoVisit(button.dataset.undoVisit,Number(button.dataset.version));
 else if(button.hasAttribute('data-close-dialog'))dialog.close();
 }catch(error){if(dialog.open)modalError(error);else toast(error.message);}});
document.addEventListener('submit',event=>{const form=event.target;if(form.id==='admin-search'){event.preventDefault();closeMore();tab='quotes';search=form.elements.q.value.trim();filter='';page=0;loadView();}if(form.id==='filter-form'){event.preventDefault();search=form.elements.q.value;filter=form.elements.status.value;page=0;loadView();}if(form.id==='agenda-form'){event.preventDefault();agendaDate=form.elements.date.value;loadView();}if(form.id==='customers-form'){event.preventDefault();search=form.elements.q.value;loadView();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.getElementById('admin-more-menu')?.hidden)closeMore(true);});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{if(needRefresh)loadView();else openPendingNotification();});
window.addEventListener('pagehide',()=>{stopAdminHeaderGlass();stop?.();clearInterval(sessionTimer);clearAdminSession();dialog.close();detail.replaceChildren();root.replaceChildren();currentQuote=currentSub=currentCustomer=null;});
window.addEventListener('pageshow',event=>{if(event.persisted)api('/api/admin/session').then(()=>shell()).catch(error=>login(error.status===401?'':error.message,error.mfaRequired));});
api('/api/admin/session').then(()=>shell()).catch(error=>login(error.status===401?'':error.message,error.mfaRequired));
